using Microsoft.Extensions.AI;
using System.ComponentModel;

Console.WriteLine("Research Agent Starting...");

var topic = args.Length > 0 ? string.Join(' ', args) : "the impact of quantum computing on cryptography";
Console.WriteLine($"Researching topic: {topic}\n");

// Configure the chat client with tool support
var innerClient = new OpenAI.OpenAIClient(
    Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "sk-placeholder")
    .GetChatClient("gpt-4o");

var researchTools = new ResearchTools();

IChatClient chatClient = new Microsoft.Extensions.AI.OpenAI.OpenAIChatClient(innerClient)
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools = [
        AIFunctionFactory.Create(researchTools.SearchWeb),
        AIFunctionFactory.Create(researchTools.SaveNote),
        AIFunctionFactory.Create(researchTools.GetNotes),
    ]
};

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a given topic thoroughly.
        Use the SearchWeb tool to find information from multiple angles.
        Use the SaveNote tool to record important findings as you go.
        Use the GetNotes tool to review what you've collected.
        After gathering enough information (at least 3 searches), review your notes
        and provide a comprehensive summary of your findings.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

var response = await chatClient.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n========== RESEARCH SUMMARY ==========\n");
Console.WriteLine(response.Text);
Console.WriteLine("\n========== COLLECTED NOTES ==========\n");
foreach (var note in researchTools.Notes)
{
    Console.WriteLine($"• {note}");
}

// --- Tool Definitions ---

public class ResearchTools
{
    private static readonly HttpClient Http = new();
    public List<string> Notes { get; } = [];

    [Description("Searches the web for information on a query. Returns search result snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query")] string query)
    {
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

        // Use a public search API (DuckDuckGo instant answer API)
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await Http.GetStringAsync(url);

            // Extract useful text from DDG response
            var doc = System.Text.Json.JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            if (root.TryGetProperty("AbstractText", out var abs) && abs.GetString() is { Length: > 0 } absText)
                results.Add($"Summary: {absText}");

            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var item in topics.EnumerateArray().Take(5))
                {
                    if (item.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                        results.Add($"- {t}");
                }
            }

            return results.Count > 0
                ? string.Join("\n", results)
                : $"No detailed results found for '{query}'. Try a more specific query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Saves a research note for later reference.")]
    public string SaveNote(
        [Description("The note content to save")] string note)
    {
        Notes.Add(note);
        Console.WriteLine($"  [Tool] Note saved ({Notes.Count} total)");
        return $"Note saved. You now have {Notes.Count} note(s).";
    }

    [Description("Retrieves all saved research notes.")]
    public string GetNotes()
    {
        if (Notes.Count == 0)
            return "No notes saved yet.";

        Console.WriteLine($"  [Tool] Retrieving {Notes.Count} notes");
        return string.Join("\n", Notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

